.view select { height: 26px; padding: 0 6px; background: transparent; color: inherit; border: 1px solid #8e8e8e;
  border-radius: 2px; }

options.afterRender:
const week = {"from": "2022-10-06T22:00:00.000Z", "to": "2022-10-13T22:00:00.000Z"};
const plots = [];
const style = ".opendt-plots { position: fixed; inset: 0; z-index: 1000; display: flex; align-items: center;\n  justify-content: center; background: rgba(0, 0, 0, 0.6); }\n.opendt-plots > div { background: var(--panel); border: 1px solid var(--line); border-radius: 4px; padding: 24px;\n  color: var(--ink); font-size: 14px; }\n.opendt-plots section { display: grid; grid-template-columns: repeat(4, auto); gap: 40px; margin: 16px 0 24px; }\n.opendt-plots label { display: flex; gap: 8px; margin-top: 10px; cursor: pointer; }\n.opendt-plots button { float: right; background: #3d71d9; color: white; border: 0; border-radius: 2px;\n  padding: 6px 16px; cursor: pointer; }";
// the links as Grafana fills them in now (the time, the markers, ...), again at every refresh
context.element.querySelectorAll('[data-href]').forEach((a) => (a.href = context.grafana.replaceVariables(a.dataset.href)));
// CSS for what lies outside the panel, added once to the page (the panel renders at every refresh), in the colours
// of Grafana's theme: var(--panel), var(--canvas), var(--line), and var(--ink)
const css = (id, text) => {
  const { background, border, text: ink } = context.grafana.theme.colors;
  const theme = ':root { --panel: ' + background.primary + '; --canvas: ' + background.canvas + '; --line: ' + border.medium + '; --ink: ' + ink.primary + ' }\n';
  document.getElementById(id) || document.head.insertAdjacentHTML('beforeend', '<style id="' + id + '">' + theme + text + '</style>');
};
// none of Grafana's own: no "Powered by Grafana" under the screen, no menus over the panels
const grafana = ['[data-testid="public-dashboard-footer"]', '[data-testid="hover-header-container"]', 'button[aria-label^="Menu for panel"]'];
css('opendt-grafana', grafana.join(', ') + ' { display: none !important; }');
// light or dark, as last chosen in this browser; Grafana takes its theme from the address, when the page loads
const light = document.body.classList.contains('theme-light');
const theme = (name) => {
  const address = new URL(location.href);
  address.searchParams.set('theme', name);
  location.replace(address);
};
const chosen = localStorage.getItem('opendt-theme');
if (chosen && (chosen === 'light') !== light) theme(chosen);
// the view: Week, Day, or 6 h, the markers, and the interval show at once on a click, kept in the address; Day and
// 6 h follow the twin, to its last hours, at every refresh; always Grafana's kiosk mode (no menus, no bars)
const address = context.grafana.locationService;
const time = context.element.querySelector('[data-time]');
const twin = time.dataset.time;
time.textContent = twin.slice(0, 16).replace('T', ' ');
// the time a window shows: Week, the SURF week; Day or 6 h, the twin's last ones, within the week, to its next full
// hour (the range moves, and the panels ask again, once an hour, not at every window)
const range = (window, twin) => {
  const hours = { day: 24, hours: 6 }[window];
  if (!hours) return week;
  const to = Math.ceil(new Date(twin).getTime() / 3600000) * 3600000;
  const from = Math.max(to - hours * 3600000, new Date(week.from).getTime());
  return { from, to: from + hours * 3600000 };
};
const shown = (key) => context.grafana.replaceVariables('$' + key);
context.element.querySelectorAll('[data-var]').forEach((choice) => {
  const { var: key, value } = choice.dataset;
  if (choice.tagName === 'SELECT') {
    choice.value = shown(key);
    choice.onchange = () => address.partial({ ['var-' + key]: choice.value });
  } else {
    choice.classList.toggle('on', shown(key) === value);
    choice.onclick = () => address.partial({ ['var-' + key]: value, ...(key === 'window' ? range(value, twin) : {}) });
  }
});
if (!('kiosk' in address.getSearchObject())) address.partial({ kiosk: true }, true);
const { from = week.from, to = week.to } = address.getSearchObject();
const end = Number(to) || Date.parse(to); // the address has milliseconds or an ISO date
const wholeWeek = from === week.from && to === week.to; // Day or 6 h before the twin's time was known
if (twin && shown('window') !== 'week' && (Date.parse(twin) > end || wholeWeek)) {
  address.partial(range(shown('window'), twin), true);
}
// ☀ or ☾, next to the twin's time: the other theme, kept in this browser (light and theme: grafana.js)
const toggle = context.element.querySelector('.theme');
toggle.textContent = light ? '☾' : '☀';
toggle.title = light ? 'Dark' : 'Light';
toggle.onclick = () => {
  localStorage.setItem('opendt-theme', light ? 'dark' : 'light');
  theme(light ? 'dark' : 'light');
};
// ☰ Plots opens the plots of the screen by row, ticked while shown: a tick shows or hides a plot at once, a row's tick
// all of its plots. The address keeps the hidden plots, so a plot added later shows, even with an old address
const hidden = () => context.grafana.replaceVariables('$' + '{hidden:csv}').split(',');
css('opendt-plots', style);
const tick = (value, label, checked) =>
  '<label><input type="checkbox" value="' + value + '"' + (checked ? ' checked' : '') + '>' + label + '</label>';
const rows = Object.fromEntries(plots.map(([row, shown]) => [row, shown.map(([key]) => key)]));
context.element.onclick = ({ target }) => {
  if (!target.closest('.plots')) return;
  const dialog = document.createElement('div');
  dialog.className = 'opendt-plots';
  dialog.innerHTML =
    '<div><b>Plots shown</b><section>' +
    plots.map(([row, shown]) => '<div>' + tick(row, '<b>' + row + '</b>', false) +
      shown.map(([key, title]) => tick(key, title, !hidden().includes(key))).join('') + '</div>').join('') +
    '</section><button>Close</button></div>';
  const box = (value) => dialog.querySelector('[value="' + value + '"]');
  // a row's tick: on while all its plots show, a dash while some do
  const mark = () => Object.entries(rows).forEach(([row, keys]) => {
    const on = keys.filter((key) => box(key).checked).length;
    box(row).checked = on === keys.length;
    box(row).indeterminate = on > 0 && on < keys.length;
  });
  mark();
  dialog.onchange = ({ target }) => {
    const keys = rows[target.value] ?? [target.value];
    keys.forEach((key) => (box(key).checked = target.checked));
    const others = hidden().filter((key) => !keys.includes(key));
    context.grafana.locationService.partial({ 'var-hidden': target.checked ? others : [...others, ...keys] }, true);
    mark();
  };
  dialog.onclick = ({ target }) => {
    if (target === dialog || target.tagName === 'BUTTON') dialog.remove();
  };
  document.body.append(dialog);
};

options.styles:
.lever { height: 100%; display: flex; flex-direction: column; justify-content: center; gap: 2px;
  padding: 0 8px; cursor: pointer; }
.lever > small { text-align: center; margin-bottom: 4px; }
.lever small { font-size: 12px; color: #8e8e8e; white-space: nowrap; }
.lever p { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; margin: 0;
  line-height: 1.3; }
.lever b { font-size: 15px; font-weight: 500; white-space: nowrap; }
.lever > small:last-child { margin: 4px 0 0; font-size: 11px; }
.lever i { font-style: normal; }
.lever a { font-size: 11px; color: #8e8e8e; white-space: nowrap; text-align: center; }
.lever:hover a { color: #6e9fff; }

options.afterRender:
const control = "http://localhost:3001/api/control";
const style = ".opendt-lever { position: absolute; z-index: 1000; display: flex; flex-direction: column; gap: 6px;\n  padding: 12px; background: var(--panel); border: 1px solid #3d71d9; border-radius: 2px; color: var(--ink);\n  font-size: 14px; }\n.opendt-lever small { font-size: 12px; color: #8e8e8e; margin-top: 4px; }\n.opendt-lever div { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }\n.opendt-lever button, .opendt-lever input { flex: 1; padding: 6px; background: var(--canvas); color: var(--ink);\n  border: 1px solid var(--line); border-radius: 2px; font-size: 14px; text-align: center; cursor: pointer; }\n.opendt-lever input { width: 4em; }\n.opendt-lever .on, .opendt-lever .apply { background: #3d71d9; border-color: #3d71d9; color: white; }";
// CSS for what lies outside the panel, added once to the page (the panel renders at every refresh), in the colours
// of Grafana's theme: var(--panel), var(--canvas), var(--line), and var(--ink)
const css = (id, text) => {
  const { background, border, text: ink } = context.grafana.theme.colors;
  const theme = ':root { --panel: ' + background.primary + '; --canvas: ' + background.canvas + '; --line: ' + border.medium + '; --ink: ' + ink.primary + ' }\n';
  document.getElementById(id) || document.head.insertAdjacentHTML('beforeend', '<style id="' + id + '">' + theme + text + '</style>');
};
// a click opens the box larger, over the screen, with what its levers take; Apply, once confirmed, sends the
// changes to the twin. Over the screen, the open box outlives the screen's refreshes
const box = context.element.querySelector('.lever');
const rows = [...box.querySelectorAll('[data-name]')];
const levers = [...box.querySelectorAll('[data-key]')];
// a choice by its label, a number with its thousands separators
const label = ({ dataset: { choices, labels } }, value) =>
  choices ? labels.split('|')[choices.split(',').indexOf(value)] : Number(value).toLocaleString('en');
levers.forEach((lever) => (lever.textContent = label(lever, lever.dataset.value)));
css('opendt-lever', style);
// a lever's choices as buttons, or its number
const edit = ({ dataset: { key, choices, labels, min = '', max = '', step = 'any' } }, draft) => choices
  ? choices.split(',').map((c, i) => '<button class="choice' + (c === draft[key] ? ' on' : '') + '" data-key="' + key + '" value="' + c + '">' + labels.split('|')[i] + '</button>').join('')
  : '<input type="number" data-key="' + key + '" min="' + min + '" max="' + max + '" step="' + step + '" value="' + draft[key] + '">';
const open = () => {
  document.querySelector('.opendt-lever')?.remove();
  const draft = Object.fromEntries(levers.map(({ dataset: { key, value } }) => [key, value]));
  const { left, top, width } = (box.closest('section') ?? box).getBoundingClientRect();
  const big = document.createElement('div');
  big.className = 'opendt-lever';
  big.style.cssText = 'left: ' + (left + scrollX) + 'px; top: ' + (top + scrollY) + 'px; width: ' + width + 'px';
  big.innerHTML =
    rows.map((row) => '<small>' + row.dataset.name + '</small><div>' + [...row.querySelectorAll('[data-key]')].map((l) => edit(l, draft)).join('to') + '</div>').join('') +
    '<div><button class="apply">Apply</button><button class="cancel">Cancel</button></div>';
  big.oninput = ({ target }) => (draft[target.dataset.key] = target.value);
  big.onclick = async ({ target }) => {
    const { key } = target.dataset;
    if (target.classList.contains('choice')) {
      draft[key] = target.value;
      big.querySelectorAll('.choice[data-key="' + key + '"]').forEach((c) => c.classList.toggle('on', c === target));
    }
    if (target.className === 'cancel') big.remove();
    if (target.className !== 'apply') return;
    const changed = levers.filter(({ dataset }) => draft[dataset.key] !== dataset.value);
    if (!changed.length) return big.remove();
    // e.g., Hosts: 277 to 300; Range of r: 3-9 to 3-10
    const text = rows.filter((row) => changed.some((l) => row.contains(l))).map((row) => {
      const mine = [...row.querySelectorAll('[data-key]')];
      const values = (value) => mine.map((l) => label(l, value(l))).join('-');
      return row.dataset.name + ': ' + values((l) => l.dataset.value) + ' to ' + values((l) => draft[l.dataset.key]);
    });
    if (!confirm(text.join('; ') + '? The twin follows from its next window.')) return;
    const change = Object.fromEntries(changed.map(({ dataset: { key, choices } }) => [key, choices ? draft[key] : Number(draft[key])]));
    const response = await fetch(control, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(change) });
    if (response.ok) {
      big.remove();
      context.grafana.notifySuccess(['OpenDT', 'Applied']);
      context.grafana.refresh();
    } else {
      const { detail } = await response.json();
      context.grafana.notifyError(['OpenDT', typeof detail === 'string' ? detail : detail.map((d) => d.msg).join('; ')]);
    }
  };
  document.body.append(big);
};
// before the twin's first window, a box has no levers yet
if (levers.length) {
  box.onclick = ({ target }) => {
    if (!target.href) open();
  };
}

